const airports={
  昆明:{code:'KMG',name:'长水国际机场',display:'昆明'},
  陇川:{code:'LCS',name:'陇川广宋机场',display:'陇川（瑞丽）'},
  兰坪:{code:'兰坪丰华通用机场',name:'兰坪',display:'兰坪'},
  凤庆:{code:'凤庆中和机场',name:'凤庆',display:'凤庆'}
};
const plans={
  '昆明-兰坪':{days:[0,1,3,5],depart:'07:00',arrive:'08:15',duration:'1小时15分',price:199,number:'JH1101'},
  '兰坪-昆明':{days:[0,1,3,5],depart:'08:55',arrive:'10:10',duration:'1小时15分',price:199,number:'JH1102'},
  '昆明-陇川-A':{days:[0,1,3,5],depart:'10:50',arrive:'12:20',duration:'1小时30分',price:299,number:'JH1201'},
  '陇川-昆明-A':{days:[0,1,3,5],depart:'13:00',arrive:'14:30',duration:'1小时30分',price:299,number:'JH1202'},
  '昆明-陇川-B':{days:[2,4,6],depart:'07:00',arrive:'08:30',duration:'1小时30分',price:299,number:'JH1203'},
  '陇川-昆明-B':{days:[2,4,6],depart:'09:10',arrive:'10:40',duration:'1小时30分',price:299,number:'JH1204'},
  '昆明-凤庆':{days:[2,4,6],depart:'11:20',arrive:'12:30',duration:'1小时10分',price:199,number:'JH1301'},
  '凤庆-昆明':{days:[2,4,6],depart:'13:10',arrive:'14:20',duration:'1小时10分',price:199,number:'JH1302'}
};
const params=new URLSearchParams(location.search),from=params.get('from')||'昆明',to=params.get('to')||'陇川',passengers=params.get('passengers')||'1 位成人';
function parseLocalDate(value){const parts=(value||'').split('-').map(Number);return parts.length===3&&parts.every(Boolean)?new Date(parts[0],parts[1]-1,parts[2]):new Date()}
function dateValue(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function addDays(date,amount){const result=new Date(date);result.setDate(result.getDate()+amount);return result}
function addMonths(date,months){const result=new Date(date.getFullYear(),date.getMonth()+months,1),lastDay=new Date(result.getFullYear(),result.getMonth()+1,0).getDate();result.setDate(Math.min(date.getDate(),lastDay));return result}
function planFor(date){const base=`${from}-${to}`,day=date.getDay();if(base==='昆明-陇川'||base==='陇川-昆明')return plans[`${base}-${[0,1,3,5].includes(day)?'A':'B'}`];const plan=plans[base];return plan?.days.includes(day)?plan:null}
function formatDate(date){return new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric',weekday:'short'}).format(date)}
const today=new Date();today.setHours(0,0,0,0);const bookingEnd=addMonths(today,10);let selectedDate=parseLocalDate(params.get('date'));if(selectedDate<today)selectedDate=new Date(today);if(selectedDate>bookingEnd)selectedDate=new Date(bookingEnd);
const fromAirport=airports[from]||{code:from,name:from,display:from},toAirport=airports[to]||{code:to,name:to,display:to};
document.querySelector('#summary-from-city').textContent=fromAirport.display;document.querySelector('#summary-to-city').textContent=toAirport.display;document.querySelector('#summary-route').textContent=`${fromAirport.code} 至 ${toAirport.code}`;document.querySelector('#summary-route').classList.toggle('airport-name-code',fromAirport.code.length>3||toAirport.code.length>3);document.querySelector('#summary-passengers').textContent=passengers;document.querySelector('#page-route').textContent=`${fromAirport.display} 至 ${toAirport.display}`;
const modifyRoutes={昆明:['陇川','兰坪','凤庆'],陇川:['昆明'],兰坪:['昆明'],凤庆:['昆明']},modifyButton=document.querySelector('#modify-search'),modifyPanel=document.querySelector('#modify-panel'),modifyFrom=document.querySelector('#modify-from'),modifyTo=document.querySelector('#modify-to'),modifyDate=document.querySelector('#modify-date'),modifyReturn=document.querySelector('#modify-return'),modifyReturnWrap=document.querySelector('#modify-return-wrap');
function airportOption(city){return new Option(`${airports[city].display} · ${airports[city].name}`,city)}
modifyFrom.replaceChildren(...Object.keys(modifyRoutes).map(airportOption));modifyFrom.value=from;
function refreshModifyDestinations(selected){modifyTo.replaceChildren(...modifyRoutes[modifyFrom.value].map(airportOption));if(selected&&modifyRoutes[modifyFrom.value].includes(selected))modifyTo.value=selected}refreshModifyDestinations(to);
modifyDate.value=dateValue(selectedDate);modifyDate.min=dateValue(today);modifyDate.max=dateValue(bookingEnd);modifyReturn.value=params.get('return')||'';modifyReturn.min=modifyDate.value;modifyReturn.max=dateValue(bookingEnd);document.querySelector('#modify-passengers').value=passengers;
const initialTrip=params.get('trip')==='round-trip'?'round-trip':'one-way';document.querySelector(`input[name="modify-trip"][value="${initialTrip}"]`).checked=true;
function updateModifyTrip(){const round=document.querySelector('input[name="modify-trip"]:checked').value==='round-trip';modifyReturnWrap.hidden=!round;modifyReturn.required=round}updateModifyTrip();
document.querySelectorAll('input[name="modify-trip"]').forEach(radio=>radio.addEventListener('change',updateModifyTrip));modifyFrom.addEventListener('change',()=>refreshModifyDestinations());modifyDate.addEventListener('change',()=>{modifyReturn.min=modifyDate.value;if(modifyReturn.value&&modifyReturn.value<modifyDate.value)modifyReturn.value=modifyDate.value});
modifyButton.addEventListener('click',()=>{const open=modifyPanel.hidden;modifyPanel.hidden=!open;modifyButton.setAttribute('aria-expanded',String(open))});
document.querySelector('#modify-swap').addEventListener('click',()=>{const oldFrom=modifyFrom.value,oldTo=modifyTo.value;if(modifyRoutes[oldTo]?.includes(oldFrom)){modifyFrom.value=oldTo;refreshModifyDestinations(oldFrom)}});
document.querySelector('#modify-form').addEventListener('submit',event=>{event.preventDefault();if(!event.currentTarget.reportValidity())return;const search=new URLSearchParams({from:modifyFrom.value,to:modifyTo.value,date:modifyDate.value,trip:document.querySelector('input[name="modify-trip"]:checked').value,passengers:document.querySelector('#modify-passengers').value});if(!modifyReturnWrap.hidden)search.set('return',modifyReturn.value);location.href=`results.html?${search}`});
const fareDialog=document.querySelector('#fare-confirm-dialog'),fareDialogBenefits=document.querySelector('#fare-dialog-benefits');let selectedFare=null;
function showFareConfirmation(choice,plan){const discount=choice.classList.contains('discount-fare'),fareName=discount?'优惠经济舱':'基础经济舱',farePrice=discount?plan.price-10:plan.price;selectedFare={name:fareName,price:farePrice,number:plan.number,depart:plan.depart,arrive:plan.arrive,baggage:discount?'none':'included'};document.querySelector('#fare-dialog-title').textContent=fareName;document.querySelector('#fare-dialog-price').textContent=farePrice;document.querySelector('#fare-dialog-route').textContent=`${fromAirport.display} 至 ${toAirport.display} · ${plan.number} · 运-12F`;const benefits=discount?[['🎒','手提行李','已包含',false],['🧳','托运行李','不含托运行李额度',true],['🍱','机上餐食','不含机上餐食',true]]:[['🎒','手提行李','已包含',false],['🧳','托运行李','已包含托运行李额度',false],['🍱','机上餐食','不含机上餐食',true]];fareDialogBenefits.replaceChildren(...benefits.map(([icon,title,text,missing])=>{const item=document.createElement('div');item.className=`benefit-item${missing?' missing':''}`;item.innerHTML=`<i>${icon}</i><strong>${title}</strong><span>${text}</span>`;return item}));fareDialog.showModal()}
document.querySelector('.fare-dialog-close').addEventListener('click',()=>fareDialog.close());document.querySelector('#fare-dialog-back').addEventListener('click',()=>fareDialog.close());document.querySelector('#fare-dialog-confirm').addEventListener('click',()=>{if(!selectedFare)return;const search=new URLSearchParams({from,to,date:dateValue(selectedDate),passengers,fare:selectedFare.name,price:selectedFare.price,flight:selectedFare.number,depart:selectedFare.depart,arrive:selectedFare.arrive,baggage:selectedFare.baggage});location.href=`extras.html?${search}`});fareDialog.addEventListener('click',event=>{if(event.target===fareDialog){const rect=fareDialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)fareDialog.close()}});
function renderDates(){document.querySelector('#summary-date').textContent=formatDate(selectedDate);const strip=document.querySelector('#date-strip');strip.replaceChildren();for(let offset=-3;offset<=3;offset++){const date=addDays(selectedDate,offset),inRange=date>=today&&date<=bookingEnd,plan=inRange?planFor(date):null,button=document.createElement('button');button.type='button';button.className=`date-option${plan?' available':''}${offset===0?' selected':''}`;button.disabled=!plan;button.innerHTML=`<b>${date.getMonth()+1}月${date.getDate()}日</b><span>${'日一二三四五六'[date.getDay()]==='日'?'周日':`周${'日一二三四五六'[date.getDay()]}`}</span><small>${plan?`¥${plan.price} 起`:inRange?'无航班':'不可选'}</small>`;button.addEventListener('click',()=>{selectedDate=date;history.replaceState(null,'',`${location.pathname}?${new URLSearchParams({...Object.fromEntries(params),date:dateValue(date)})}`);render()});strip.append(button)}document.querySelector('#previous-days').disabled=selectedDate<=today;document.querySelector('#next-days').disabled=selectedDate>=bookingEnd}
function renderFlight(){const container=document.querySelector('#flight-results'),plan=planFor(selectedDate);container.replaceChildren();document.querySelector('#flight-count').textContent=plan?'1 个航班':'0 个航班';if(!plan){const empty=document.createElement('div');empty.className='empty-state';empty.innerHTML='<h2>当天暂无航班</h2><p>请选择上方标有价格的日期，查看可售航班。</p><a href="index.html#timetable">查看完整航班计划</a>';container.append(empty);return}const card=document.querySelector('#flight-card-template').content.cloneNode(true);card.querySelector('.depart-time').textContent=plan.depart;card.querySelector('.arrive-time').textContent=plan.arrive;card.querySelector('.from-city').textContent=fromAirport.display;card.querySelector('.to-city').textContent=toAirport.display;card.querySelector('.from-code').textContent=fromAirport.code;card.querySelector('.to-code').textContent=toAirport.code;card.querySelector('.from-code').classList.toggle('airport-name-code',fromAirport.code.length>3);card.querySelector('.to-code').classList.toggle('airport-name-code',toAirport.code.length>3);card.querySelector('.from-airport').textContent=fromAirport.name;card.querySelector('.to-airport').textContent=toAirport.name;card.querySelector('.duration').textContent=plan.duration;card.querySelector('.flight-number').textContent=`${plan.number} · 运-12F`;card.querySelector('.price').textContent=plan.price;card.querySelector('.base-price').textContent=plan.price;card.querySelector('.discount-price').textContent=plan.price-10;const details=card.querySelector('.flight-details'),detailsButton=card.querySelector('.details-button'),fareSelector=card.querySelector('.fare-selector'),economyButton=card.querySelector('.economy');detailsButton.addEventListener('click',()=>{details.hidden=!details.hidden;detailsButton.textContent=details.hidden?'查看航班详情⌄':'收起航班详情⌃'});function toggleFares(show=fareSelector.hidden){fareSelector.hidden=!show;economyButton.classList.toggle('chosen',show);economyButton.querySelector('i').textContent=show?'⌃':'⌄'}economyButton.addEventListener('click',()=>toggleFares());card.querySelector('.close-fares').addEventListener('click',()=>toggleFares(false));card.querySelectorAll('.fare-choice:not(.unavailable-fare)').forEach(choice=>choice.addEventListener('click',()=>{card.querySelectorAll('.fare-choice').forEach(item=>item.classList.remove('selected'));choice.classList.add('selected');showFareConfirmation(choice,plan)}));container.append(card)}
function render(){renderDates();renderFlight()}document.querySelector('#previous-days').addEventListener('click',()=>{if(selectedDate>today)selectedDate=addDays(selectedDate,-1);render()});document.querySelector('#next-days').addEventListener('click',()=>{if(selectedDate<bookingEnd)selectedDate=addDays(selectedDate,1);render()});render();
